import type { DeepLesson, DeepSection, DeepFormula, DeepWorkedExample, DeepAssessment } from "../deepLessonTypes";

const letters = ["A", "B", "C", "D"] as const;
function section(moduleId: string, title: string, lead: string, paragraphs: string[], keyPoints: string[], mini: [string, string, string]): DeepSection {
  return { moduleId, title, lead, paragraphs, keyPoints, miniExample: { title: "A quick application", setup: mini[0], walkthrough: [mini[1]], takeaway: mini[2] } };
}
function formula(id: string, title: string, latex: string, variables: [string, string, string][], assumptions: string[], domain: string, interpretation: string): DeepFormula {
  return { id, title, latex, variables: variables.map(([symbol, meaning, unit]) => ({ symbol, meaning, unit })), assumptions, domain, interpretation };
}
function example(moduleId: string, title: string, given: string[], find: string, plan: string, steps: string[], interpret: string, sanityCheck: string): DeepWorkedExample {
  return { id: `${moduleId}-worked`, moduleIds: [moduleId], title, given, find, plan, steps: steps.map((result, i) => ({ label: `Step ${i + 1}`, result })), interpret, sanityCheck };
}
function question(id: string, objective: string, skill: DeepAssessment["skill"], prompt: string, options: [string, string][], correct: number, solution: string[]): DeepAssessment {
  return { id, objectiveIds: [objective], skill, prompt, options: options.map(([text, feedback], i) => ({ id: letters[i], text, feedback })), correctOptionId: letters[correct], solution };
}
function lesson(readingId: number, title: string, sections: DeepSection[], formulas: DeepFormula[], workedExamples: DeepWorkedExample[], misconceptions: [string, string][], assessments: DeepAssessment[]): DeepLesson {
  return { readingId, title, sections, formulas, workedExamples, misconceptions: misconceptions.map(([claim, correction]) => ({ claim, correction })), assessments };
}

